
'use client'
import style from './registro.module.css'


import Form from '@/components/ui/forms/formulario'
import Input from '@/components/ui/input/campos'
import Card from '@/components/ui/card/card';

import { usuarioPayload, usuarioSchema } from '@/schemas/usuarioSchema';
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from 'react-hook-form';

function registro() {
    const {
        register,
        handleSubmit,
        formState: { errors, isSubmitting },
    } = useForm<usuarioPayload>({
        resolver: zodResolver(usuarioSchema),
    });

    const onSubmitForm = (datos: usuarioPayload) => {
        console.log('Datos enviados:', datos);
    };

    return (
        <Card>
            <Form onSubmit={handleSubmit(onSubmitForm)} columns={2} >
                <h1 >registro</h1>

                <Input
                    label="Campo dinámico"
                    name="doc"
                    placeholder="Escribe algo..."
                    register={register('doc')}
                    error={errors.doc}
                />

                <Input
                    label="Campo dinámico"
                    name="doc"
                    placeholder="Escribe algo..."
                    register={register('doc')}
                    error={errors.doc}
                />

                <Input
                    label="Campo dinámico"
                    name="doc"
                    placeholder="Escribe algo..."
                    register={register('doc')}
                    error={errors.doc}
                />

                <Input
                    label="Campo dinámico"
                    name="doc"
                    placeholder="Escribe algo..."
                    register={register('doc')}
                    error={errors.doc}
                />

            </Form>
        </Card>
    )
}

export default registro
